WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY cost NULLS FIRST, id) AS rn FROM shipments QUALIFY rn = 1) SELECT s.id, s.order_id, s.shipped_date, s.delivered_date, s.cost, s.status, s.rn, CASE WHEN status RLIKE '^(RETURNED|DELIVERED)$' THEN 'CORE' WHEN status RLIKE '^(IN_TRANSIT|LOST)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS status_zone, (SELECT MAX(x.quantity) FROM order_items x WHERE x.order_id = s.order_id) AS max_order_item_quantity FROM ranked s ORDER BY id
